import{_ as t,o as n,c as i,a2 as r}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Sitzplätze","description":"Wie Sitzplätze für Bearbeitungsrechte in ApptiveGrid funktionieren und wann sie knapp werden.","frontmatter":{"title":"Sitzplätze","description":"Wie Sitzplätze für Bearbeitungsrechte in ApptiveGrid funktionieren und wann sie knapp werden."},"headers":[],"relativePath":"zusammenarbeit/sitzplaetze.md","filePath":"zusammenarbeit/sitzplaetze.md","lastUpdated":1786093505000}'),a={name:"zusammenarbeit/sitzplaetze.md"};function s(l,e,d,o,h,c){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="sitzplatze" tabindex="-1">Sitzplätze <a class="header-anchor" href="#sitzplatze" aria-label="Permalink to &quot;Sitzplätze&quot;">​</a></h1><p>Ein <strong>Sitzplatz</strong> ist eine Lizenz für eine Person mit Bearbeitungsrechten in einem Space.</p><h2 id="die-grundregel" tabindex="-1">Die Grundregel <a class="header-anchor" href="#die-grundregel" aria-label="Permalink to &quot;Die Grundregel&quot;">​</a></h2><blockquote><p><em>Der Eigentümer kann zusätzliche Plätze für NutzerInnen mit Bearbeitungsrechten erwerben. Leserechte sind kostenfrei.</em></p></blockquote><p>Konkret:</p><table tabindex="0"><thead><tr><th>Rolle</th><th style="text-align:center;">Belegt einen Platz</th></tr></thead><tbody><tr><td><strong>Ansehen</strong></td><td style="text-align:center;">nein</td></tr><tr><td><strong>Bearbeiten</strong></td><td style="text-align:center;">ja</td></tr><tr><td><strong>Managen</strong></td><td style="text-align:center;">ja</td></tr><tr><td><strong>Eigentümer</strong></td><td style="text-align:center;">ja</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Beliebig viele Lesende</p><p>Sie können unbegrenzt Personen mit der Rolle <em>Ansehen</em> in einen Space aufnehmen, ohne Plätze zu verbrauchen. Für Stakeholder, Kunden oder angrenzende Abteilungen, die nur mitlesen sollen, ist das der richtige Weg.</p></div><h2 id="verfugbare-platze-prufen" tabindex="-1">Verfügbare Plätze prüfen <a class="header-anchor" href="#verfugbare-platze-prufen" aria-label="Permalink to &quot;Verfügbare Plätze prüfen&quot;">​</a></h2><p>Öffnen Sie <strong>Space-Einstellungen → Allgemein</strong>. Dort steht:</p><blockquote><p><em>Verfügbare Plätze für NutzerInnen mit Bearbeitungsrechten:</em></p></blockquote><p>Über <strong>Plätze anpassen</strong> ändert der Eigentümer die Anzahl.</p><div class="warning custom-block"><p class="custom-block-title">Plätze gelten je Space</p><p>Die Anzahl hängt am einzelnen Space, nicht am Konto. Arbeiten Sie mit mehreren Spaces, hat jeder seine eigenen Plätze.</p></div><h2 id="wenn-die-platze-nicht-reichen" tabindex="-1">Wenn die Plätze nicht reichen <a class="header-anchor" href="#wenn-die-platze-nicht-reichen" aria-label="Permalink to &quot;Wenn die Plätze nicht reichen&quot;">​</a></h2><p>Laden Sie mehr Personen mit Bearbeitungsrechten ein als Plätze vorhanden sind, meldet ApptiveGrid:</p><blockquote><p><strong>Überschreitung der lizenzierten Plätze in Ihrem Tarif</strong></p><p><em>Es scheint, als hätten Sie mehr Benutzer eingeladen, als Sie lizenzierte Plätze für NutzerInnen haben.</em></p><p><em>Sie benötigen {Anzahl} weitere Plätze.</em></p><p><em>Ändern Sie die Berechtigungen von Benutzern auf „Nur Lesen&quot; oder buchen Sie weitere Plätze.</em></p></blockquote><p>Zwei Wege aus der Situation:</p><p><strong>1. Rollen herabstufen.</strong> Gehen Sie die Liste <em>Geteilt mit</em> durch und setzen Sie alle, die nicht wirklich bearbeiten müssen, auf <strong>Ansehen</strong>. Das ist kostenfrei und wirkt sofort.</p><p><strong>2. Plätze nachbuchen.</strong> Über <em>Plätze anpassen</em> in den Space-Einstellungen. Nur der Eigentümer kann das.</p><div class="tip custom-block"><p class="custom-block-title">Erst aufräumen, dann buchen</p><p>Erfahrungsgemäß haben in gewachsenen Spaces mehr Personen Bearbeitungsrechte, als sie brauchen — oft, weil bei der Einladung nicht darüber nachgedacht wurde. Eine Durchsicht der Rollenliste ist meist billiger als zusätzliche Plätze.</p><p>Denken Sie dabei auch an ausgeschiedene Mitarbeitende: Wer den Space nicht mehr braucht, sollte ganz entfernt werden.</p></div><h2 id="wer-keinen-platz-braucht" tabindex="-1">Wer keinen Platz braucht <a class="header-anchor" href="#wer-keinen-platz-braucht" aria-label="Permalink to &quot;Wer keinen Platz braucht&quot;">​</a></h2><p>Ein häufiges Missverständnis: Nicht jede Person, die mit Ihren Daten arbeitet, braucht einen Sitzplatz.</p><table tabindex="0"><thead><tr><th>Diese Person …</th><th>Braucht einen Platz?</th></tr></thead><tbody><tr><td>füllt ein öffentliches Formular aus</td><td>nein — kein Konto nötig</td></tr><tr><td>füllt ein auf den Space beschränktes Formular aus</td><td>nein — Rolle <em>Ansehen</em> genügt</td></tr><tr><td>sieht eine geteilte Ansicht über einen Link</td><td>nein</td></tr><tr><td>nutzt ein veröffentlichtes Portal</td><td>nein</td></tr><tr><td>liest Daten im Space mit</td><td>nein — Rolle <em>Ansehen</em></td></tr><tr><td>ändert Einträge im Space</td><td><strong>ja</strong></td></tr><tr><td>baut Formulare, Ansichten oder Flows</td><td><strong>ja</strong></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Datenerfassung ohne Sitzplätze</p><p>Sollen viele Personen regelmäßig Daten liefern, ohne im Space zu arbeiten, ist ein <strong>Formular</strong> fast immer die richtige Lösung — nicht eine Einladung. Formulare kosten keine Plätze, unabhängig davon, wie viele Menschen sie ausfüllen.</p></div><h2 id="testphase" tabindex="-1">Testphase <a class="header-anchor" href="#testphase" aria-label="Permalink to &quot;Testphase&quot;">​</a></h2><p>Neue Spaces starten mit einer Testphase. Die Space-Einstellungen zeigen:</p><blockquote><p><em>Test-Phase verbleibende Tage:</em></p></blockquote><p>Während der Testphase stehen erweiterte Funktionen zur Verfügung. Danach gelten die Grenzen des gebuchten Tarifs.</p><div class="warning custom-block"><p class="custom-block-title">Nach der Testphase können Einstellungen entfallen</p><p>Läuft die Testphase aus oder wird ein Tarif herabgestuft, entfernt ApptiveGrid Einstellungen, die im niedrigeren Tarif nicht enthalten sind — insbesondere bei Formularen.</p><p>Notieren Sie sich vor einem Wechsel, welche kostenpflichtigen Funktionen Sie verwenden, damit Sie den Verlust nicht erst im laufenden Betrieb bemerken.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/zusammenarbeit/rollen">Rollen</a></li><li><a href="/zusammenarbeit/personen-einladen">Personen einladen</a></li><li><a href="/spaces/einstellungen">Space-Einstellungen</a> — Plätze anpassen</li></ul>',30)])])}const g=t(a,[["render",s]]);export{p as __pageData,g as default};
